import { useContext, useEffect, useMemo, useRef, useState } from "react";
import { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { Core } from "cytoscape";
import {
  Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BadgeCheck, Boxes, Check,
  CircleAlert, CircleCheck, Clock3, Code2, ExternalLink, FileCode2, FileText,
  GitBranch, LoaderCircle, LockKeyhole, Network, Plus, ScanLine, Search, ShieldAlert,
  ShieldCheck, SlidersHorizontal, Sparkles, Sun, Upload, X,
} from "lucide-react";
import {
  Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis,
} from "recharts";
import { engineBlob, engineGet, enginePost, engineText, engineUpload } from "../api";
import { WorkspaceContext } from "./Workspace";

export type Finding = {
  id: string; rule_id: string; title: string; severity: string; file: string; line: number;
  snippet: string; sink_type: string; pii_category: string; route?: string | null;
  dpdp_section: string; remediation: string; verified?: boolean; taint_path?: Array<Record<string, unknown>>;
};
export type Scan = {
  id: string; owner?: string | null; repo: string; source: string; created_at?: string;
  score: number; grade: string; files_scanned: number; parse_errors: number; ignored_files: number;
  languages: Array<{ name: string; files: number }>; findings: Finding[]; scan_hash: string;
  sdk_inventory?: Array<{ name: string; versions: string[] }>; outbound_hosts?: string[];
  erasure_coverage?: { stores: number; covered: number; percent: number };
  test_framework?: string; test_setup_config?: string | null; score_details?: Record<string, unknown>;
};
type Rule = { id: string; name: string; severity: string; dpdp_mapping: string; remediation: string; languages: string[] };
type Capability = { ai: { provider: string; configured: boolean; model: string }; analysis: Record<string, boolean>; lineage: { backend: string } };
type GraphNode = { id: string; kind: string; properties: Record<string, unknown> };
type Graph = { scan_id: string; backend: string; nodes: GraphNode[]; edges: Array<{ id: string; source: string; target: string; type: string; properties: Record<string, unknown> }> };
type ScanList = { scans: Scan[]; count: number };

const severityColors: Record<string, string> = { critical: "#f87171", high: "#fb7185", medium: "#fbbf24", low: "#60a5fa" };
const severityOrder = ["critical", "high", "medium", "low"];
const dpdpDescriptions: Record<string, string> = {
  "§5": "Purpose limitation and consent", "§8(5)": "Reasonable security safeguards",
  "§8(6)": "Personal data breach notification", "§9": "Processing children’s personal data",
};

function useScans() { return useQuery({ queryKey: ["scans"], queryFn: () => engineGet<ScanList>("/api/v1/scans?limit=100"), staleTime: 20_000 }); }
function useScan(id?: string) { return useQuery({ queryKey: ["scan", id], queryFn: () => engineGet<Scan>(`/api/v1/scans/${id}`), enabled: Boolean(id) }); }
function dateLabel(value?: string) { if (!value) return "Just now"; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }); }
function repoLabel(scan: Scan) { return scan.owner ? `${scan.owner}/${scan.repo}` : scan.repo; }
function readVerifiedPatches(scanId: string): Record<string, string> {
  try {
    const parsed = JSON.parse(window.sessionStorage.getItem(`pl_verified_patches:${scanId}`) || "{}");
    return parsed && typeof parsed === "object" ? parsed as Record<string, string> : {};
  } catch { return {}; }
}
function download(name: string, type: string, body: string) { const url = URL.createObjectURL(new Blob([body], { type })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function downloadBlob(name: string, body: Blob) { const url = URL.createObjectURL(body); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function formatBytes(value: number) { if (value < 1024) return `${value} B`; if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`; return `${(value / 1024 / 1024).toFixed(1)} MB`; }

function PageHeading({ kicker, title, description, action }: { kicker: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="page-heading"><div><div className="console-kicker"><span className="status-dot" />{kicker}</div><h1>{title}<span className="title-period">.</span></h1><p>{description}</p></div>{action && <div className="page-heading-action">{action}</div>}</div>;
}
function ErrorBanner({ error }: { error: unknown }) { if (!error) return null; const message = error instanceof Error ? error.message : typeof error === "string" ? error : "The request failed. Please try again."; return <div className="console-error" role="alert"><CircleAlert size={16} /><span>{message}</span></div>; }
function LoadingCard({ label = "Loading workspace data…" }: { label?: string }) { return <div className="loading-card"><LoaderCircle size={18} className="spin" /><span>{label}</span></div>; }
function EmptyState({ title, copy, action }: { title: string; copy: string; action?: React.ReactNode }) { return <div className="empty-state"><span className="empty-icon"><ScanLine size={21} /></span><h3>{title}</h3><p>{copy}</p>{action}</div>; }
function SeverityTag({ severity }: { severity: string }) { return <span className={`severity-tag severity-${severity}`}><i />{severity}</span>; }
function ScoreBadge({ score, grade }: { score: number; grade: string }) { return <span className={`score-badge grade-${grade.toLowerCase()}`}><b>{grade}</b><span>{Number(score || 0).toFixed(0)}</span></span>; }
function ScanLink({ scan, children }: { scan: Scan; children: React.ReactNode }) { return <Link to={`/workspace/scans/${scan.id}`} className="scan-link">{children}</Link>; }

export function OverviewPage() {
  const query = useScans(); const scans = query.data?.scans || []; const latest = scans[0];
  const findings = latest?.findings || [];
  const verified = findings.filter((finding) => finding.verified).length;
  const severityData = severityOrder.map((name) => ({ name, value: findings.filter((finding) => finding.severity === name).length })).filter((item) => item.value > 0);
  const categoryData = Object.entries(findings.reduce<Record<string, number>>((all, finding) => { all[finding.pii_category] = (all[finding.pii_category] || 0) + 1; return all; }, {})).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const trendData = [...scans].slice(0, 8).reverse().map((scan, index) => ({ name: `Scan ${index + 1}`, score: scan.score, grade: scan.grade }));
  const risk = latest ? 100 - latest.score : 0;
  if (query.isLoading) return <LoadingCard />;
  return <div className="page-stack">
    <PageHeading kicker="PRIVACY POSTURE" title="Your privacy, in focus" description="A live view of personal data flows, code risks, and verified remediation." action={<Link className="primary-action" to="/workspace/scans/new"><Plus size={16} /> Start a scan</Link>} />
    <ErrorBanner error={query.error} />
    <div className="welcome-ribbon"><div className="ribbon-icon"><ShieldCheck size={20} /></div><div><b>{latest ? `Latest scan · ${repoLabel(latest)}` : "Your private analysis workspace is ready"}</b><span>{latest ? `${dateLabel(latest.created_at)} · ${latest.files_scanned} source files analyzed` : "Scan a GitHub repository or upload a ZIP to map where personal data flows."}</span></div><Link to={latest ? `/workspace/scans/${latest.id}` : "/workspace/scans/new"}>{latest ? "Review scan" : "Run first scan"}<ArrowRight size={15} /></Link></div>
    <section className="metric-grid">
      <article className="metric-card"><div className="metric-head"><span>PRIVACY POSTURE</span><span className="metric-icon teal"><ShieldCheck size={16} /></span></div><div className="metric-value">{latest ? <>{latest.score.toFixed(0)}<small>/100</small></> : "—"}</div><div className="metric-foot"><span className={`grade-label grade-${latest?.grade.toLowerCase() || "empty"}`}>{latest ? `Grade ${latest.grade}` : "No scan yet"}</span><span>{latest ? `${risk.toFixed(0)} risk points` : "Scan code to establish a baseline"}</span></div></article>
      <article className="metric-card"><div className="metric-head"><span>OPEN FINDINGS</span><span className="metric-icon red"><ShieldAlert size={16} /></span></div><div className="metric-value">{latest ? findings.filter((item) => !item.verified).length : "—"}</div><div className="metric-foot"><span className="metric-danger">{findings.filter((item) => item.severity === "critical" || item.severity === "high").length} critical / high</span><span>Latest scan</span></div></article>
      <article className="metric-card"><div className="metric-head"><span>VERIFIED FIXES</span><span className="metric-icon green"><BadgeCheck size={16} /></span></div><div className="metric-value">{latest ? verified : "—"}</div><div className="metric-foot"><span className="metric-success">Rescan verified</span><span>Fixes in latest scan</span></div></article>
      <article className="metric-card"><div className="metric-head"><span>ERASURE COVERAGE</span><span className="metric-icon indigo"><Activity size={16} /></span></div><div className="metric-value">{latest ? `${latest.erasure_coverage?.percent ?? 100}<small>%</small>` : "—"}</div><div className="metric-foot"><span>{latest ? `${latest.erasure_coverage?.covered ?? 0} of ${latest.erasure_coverage?.stores ?? 0} stores covered` : "Mapped from detected stores"}</span><span>Latest scan</span></div></article>
    </section>
    <section className="dashboard-grid">
      <article className="console-card trend-card"><div className="card-heading"><div><h2>Posture trend</h2><p>Score across recent repository scans</p></div><Link to="/workspace/scans">All scans <ArrowUpRight size={14} /></Link></div>{trendData.length > 1 ? <div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData} margin={{ left: -20, right: 12, top: 12, bottom: 0 }}><defs><linearGradient id="scoreFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2dd4bf" stopOpacity={0.24} /><stop offset="100%" stopColor="#2dd4bf" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid stroke="#202a34" strokeDasharray="4 4" vertical={false} /><XAxis dataKey="name" tick={{ fill: "#71808d", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis domain={[0, 100]} tick={{ fill: "#71808d", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ background: "#121a22", border: "1px solid #263541", borderRadius: 8, color: "#e7edf3", fontSize: 11 }} /><Area type="monotone" dataKey="score" stroke="#2dd4bf" strokeWidth={2.5} fill="url(#scoreFill)" activeDot={{ r: 4, fill: "#2dd4bf" }} /></AreaChart></ResponsiveContainer></div> : <EmptyState title={latest ? "One scan in your history" : "No trend yet"} copy={latest ? "Run another scan to see how your privacy posture changes over time." : "Your score trend will appear here after your first scan."} action={!latest && <Link className="text-action" to="/workspace/scans/new">Scan a repository <ArrowRight size={14} /></Link>} />}</article>
      <article className="console-card severity-card"><div className="card-heading"><div><h2>Severity mix</h2><p>Findings in the latest scan</p></div><Link to="/workspace/findings">Details <ArrowUpRight size={14} /></Link></div>{severityData.length ? <div className="severity-chart-wrap"><div className="severity-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={severityData} dataKey="value" nameKey="name" innerRadius="67%" outerRadius="91%" paddingAngle={3} stroke="none">{severityData.map((item) => <Cell key={item.name} fill={severityColors[item.name]} />)}</Pie><Tooltip contentStyle={{ background: "#121a22", border: "1px solid #263541", borderRadius: 8, color: "#e7edf3", fontSize: 11 }} /></PieChart></ResponsiveContainer><div className="donut-center"><b>{findings.length}</b><span>findings</span></div></div><div className="severity-legend">{severityOrder.map((name) => <div key={name}><span className={`legend-dot severity-${name}`} />{name}<b>{findings.filter((item) => item.severity === name).length}</b></div>)}</div></div> : <EmptyState title="No findings to chart" copy="A scan’s severity breakdown will show here." />}</article>
    </section>
    <section className="dashboard-grid dashboard-grid-lower">
      <article className="console-card recent-card"><div className="card-heading"><div><h2>Recent scans</h2><p>Your latest repository activity</p></div><Link to="/workspace/scans">View history <ArrowUpRight size={14} /></Link></div>{scans.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Repository</th><th>Source</th><th>Posture</th><th>Findings</th><th>Scanned</th><th /></tr></thead><tbody>{scans.slice(0, 5).map((scan) => <tr key={scan.id}><td><ScanLink scan={scan}><span className="repo-avatar"><Code2 size={14} /></span><span className="repo-name">{repoLabel(scan)}<small>{scan.languages?.map((item) => item.name).join(", ") || "source code"}</small></span></ScanLink></td><td><span className="source-pill">{scan.source === "github" ? "GitHub" : scan.source === "sandbox" ? "Verified rescan" : "ZIP upload"}</span></td><td><ScoreBadge score={scan.score} grade={scan.grade} /></td><td><span className="table-findings">{scan.findings?.length || 0}</span></td><td className="muted-cell">{dateLabel(scan.created_at)}</td><td><ScanLink scan={scan}><ArrowRight size={14} /></ScanLink></td></tr>)}</tbody></table></div> : <EmptyState title="No scans yet" copy="Connect a repository or upload source code to see your analysis history." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start first scan</Link>} />}</article>
      <article className="console-card category-card"><div className="card-heading"><div><h2>Data categories</h2><p>Personal data seen in code sinks</p></div><span className="card-small-count">{categoryData.length} types</span></div>{categoryData.length ? <div className="category-list">{categoryData.map(([name, count], index) => <div className="category-row" key={name}><span className={`category-rank rank-${index + 1}`}>{String(index + 1).padStart(2, "0")}</span><span className="category-name">{name}</span><span className="category-meter"><i style={{ width: `${Math.max(7, count / categoryData[0][1] * 100)}%` }} /></span><b>{count}</b></div>)}</div> : <EmptyState title="No exposure mapped" copy="PII categories will appear once a repository has been scanned." />}</article>
    </section>
  </div>;
}

export function NewScanPage() {
  const navigate = useNavigate(); const client = useQueryClient(); const { aiEnabled } = useContext(WorkspaceContext);
  const [mode, setMode] = useState<"github" | "zip">("github"); const [owner, setOwner] = useState(""); const [repo, setRepo] = useState(""); const [ref, setRef] = useState(""); const [token, setToken] = useState("");
  const [file, setFile] = useState<File | null>(null); const [rules, setRules] = useState<string[] | null>(() => { try { const value = window.sessionStorage.getItem("pl_rules"); return value === null ? null : JSON.parse(value); } catch { return null; } }); const [error, setError] = useState("");
  const ruleQuery = useQuery({ queryKey: ["rules"], queryFn: () => engineGet<{ rules: Rule[] }>("/api/v1/rules") });
  const availableRules = ruleQuery.data?.rules || []; const activeRules = rules ?? availableRules.map((item) => item.id);
  const scanMutation = useMutation({ mutationFn: async () => {
    setError(""); if (!activeRules.length) throw new Error("Select at least one rule to run this scan.");
    if (mode === "github") {
      if (!owner.trim() || !repo.trim()) throw new Error("Enter the repository owner and name.");
      return enginePost<Scan>("/api/v1/scans/github", { owner: owner.trim(), repo: repo.trim(), ref: ref.trim() || undefined, token: token.trim() || undefined, rule_ids: activeRules });
    }
    if (!file) throw new Error("Choose a repository ZIP file first.");
    const form = new FormData(); form.append("file", file); form.append("rules", activeRules.join(","));
    return engineUpload<Scan>("/api/v1/scans/upload", form);
  }, onSuccess: async (scan) => { setToken(""); await client.invalidateQueries({ queryKey: ["scans"] }); await client.setQueryData(["scan", scan.id], scan); navigate(`/workspace/scans/${scan.id}`); }, onError: (caught) => setError(caught instanceof Error ? caught.message : "The scan could not be started.") });
  function toggleRule(id: string) { setRules((current) => { const effective = current ?? availableRules.map((item) => item.id); const next = effective.includes(id) ? effective.filter((item) => item !== id) : [...effective, id]; window.sessionStorage.setItem("pl_rules", JSON.stringify(next)); return next; }); }
  return <div className="page-stack"><PageHeading kicker="ANALYZE SOURCE" title="Start a new scan" description="Analyze a repository snapshot. Source files are scanned without being executed." /><ErrorBanner error={error || ruleQuery.error} />
    <div className="scan-setup-grid"><section className="console-card scan-form-card"><div className="scan-tabs" role="tablist"><button className={mode === "github" ? "selected" : ""} role="tab" aria-selected={mode === "github"} onClick={() => setMode("github")}><GitBranch size={16} /> GitHub repository</button><button className={mode === "zip" ? "selected" : ""} role="tab" aria-selected={mode === "zip"} onClick={() => setMode("zip")}><Upload size={16} /> Upload ZIP</button></div>
      {mode === "github" ? <div className="scan-form-body"><div className="form-section-heading"><span className="section-step">01</span><div><h2>Repository source</h2><p>Public repositories need no token. A fine-grained PAT is only required for private repositories.</p></div></div><div className="field-grid"><label className="console-field"><span>Owner or organization</span><input value={owner} onChange={(event) => setOwner(event.target.value)} placeholder="e.g. codechakra" autoComplete="off" /></label><label className="console-field"><span>Repository name</span><input value={repo} onChange={(event) => setRepo(event.target.value)} placeholder="e.g. privacy-demo" autoComplete="off" /></label></div><label className="console-field"><span>Branch or tag <small>OPTIONAL</small></span><input value={ref} onChange={(event) => setRef(event.target.value)} placeholder="Default branch" autoComplete="off" /></label><label className="console-field"><span>GitHub token <small>OPTIONAL · NEVER STORED</small></span><input type="password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="github_pat_…" autoComplete="new-password" /><small className="field-footnote">The token is sent only to GitHub for this scan request and is not retained.</small></label></div> : <div className="scan-form-body"><div className="form-section-heading"><span className="section-step">01</span><div><h2>Repository archive</h2><p>Upload a ZIP up to 50 MB. Archives are checked for unsafe paths and never executed.</p></div></div><label className={`drop-zone${file ? " file-selected" : ""}`}><input type="file" accept=".zip,application/zip" onChange={(event) => setFile(event.target.files?.[0] || null)} /><span className="upload-glyph">{file ? <FileCode2 size={22} /> : <Upload size={22} />}</span><b>{file ? file.name : "Drop a ZIP archive here"}</b><span>{file ? `${formatBytes(file.size)} · ready to scan` : "or browse files · ZIP only"}</span>{file && <button type="button" className="remove-file" aria-label="Remove selected archive" onClick={(event) => { event.preventDefault(); setFile(null); }}><X size={15} /></button>}</label></div>}
      <div className="scan-form-footer"><div><LockKeyhole size={14} /><span>Private · no code execution · source snapshot is not retained after scan</span></div><button className="primary-action" onClick={() => scanMutation.mutate()} disabled={scanMutation.isPending || ruleQuery.isLoading}>{scanMutation.isPending ? <><LoaderCircle size={15} className="spin" /> Scanning source…</> : <><ScanLine size={15} /> Scan repository</>}</button></div>
    </section><aside className="scan-side-stack"><section className="console-card scan-summary-card"><div className="card-heading"><div><h2>Scan configuration</h2><p>Deterministic privacy analysis</p></div><SlidersHorizontal size={16} /></div><div className="config-row"><span>Rules active</span><b>{activeRules.length}<small> / {availableRules.length || "—"}</small></b></div><div className="config-row"><span>AI fixer</span><b className={aiEnabled ? "config-on" : ""}>{aiEnabled ? "Enabled" : "Offline"}</b></div><div className="config-row"><span>Source files</span><b>JS · TS · Python · Java · C/C++</b></div><p className="config-note">AI is only used for patch drafts. Findings always come from the deterministic scanner, and fixes must clear a sandbox rescan.</p></section>
      <section className="console-card rule-pick-card"><div className="card-heading"><div><h2>Rule selection</h2><p>Choose checks for this scan</p></div><button className="text-action" onClick={() => { const all = availableRules.map((item) => item.id); setRules(all); window.sessionStorage.setItem("pl_rules", JSON.stringify(all)); }}>All</button></div>{ruleQuery.isLoading ? <LoadingCard label="Loading rule catalog…" /> : <div className="rule-pick-list">{availableRules.map((rule) => <label key={rule.id} className="rule-pick"><input type="checkbox" checked={activeRules.includes(rule.id)} onChange={() => toggleRule(rule.id)} /><span className="rule-check"><Check size={11} /></span><span><b>{rule.id}</b><small>{rule.name}</small></span><i className={`rule-severity severity-${rule.severity}`}>{rule.severity}</i></label>)}</div>}<Link to="/workspace/rules" className="view-rules-link">Configure rules <ArrowRight size={13} /></Link></section></aside></div>
  </div>;
}

export function ScanListPage() {
  const query = useScans(); const [searchParams, setSearchParams] = useSearchParams(); const q = searchParams.get("q") || ""; const [severity, setSeverity] = useState("all");
  const scans = query.data?.scans || []; const filtered = scans.filter((scan) => `${repoLabel(scan)} ${scan.source} ${scan.languages?.map((language) => language.name).join(" ")}`.toLowerCase().includes(q.toLowerCase()));
  return <div className="page-stack"><PageHeading kicker="REPOSITORY ACTIVITY" title="Scan history" description="Review source snapshots, privacy posture, and findings over time." action={<Link className="primary-action" to="/workspace/scans/new"><Plus size={16} /> New scan</Link>} /><ErrorBanner error={query.error} />
    <div className="filter-bar"><label className="filter-search"><Search size={15} /><input value={q} onChange={(event) => setSearchParams(event.target.value ? { q: event.target.value } : {})} placeholder="Filter repositories…" /></label><span className="filter-count">{filtered.length} scans</span><select aria-label="Filter scan severity" value={severity} onChange={(event) => setSeverity(event.target.value)}><option value="all">All severities</option>{severityOrder.map((item) => <option key={item} value={item}>{item}</option>)}</select></div>
    {query.isLoading ? <LoadingCard /> : filtered.length ? <div className="console-card table-card"><div className="table-scroll"><table className="data-table full-table"><thead><tr><th>Repository snapshot</th><th>Source</th><th>Score</th><th>Findings</th><th>Languages</th><th>Created</th><th /></tr></thead><tbody>{filtered.filter((scan) => severity === "all" || scan.findings.some((finding) => finding.severity === severity)).map((scan) => <tr key={scan.id}><td><ScanLink scan={scan}><span className="repo-avatar"><Code2 size={14} /></span><span className="repo-name">{repoLabel(scan)}<small>#{scan.id.slice(0, 8)}</small></span></ScanLink></td><td><span className="source-pill">{scan.source === "github" ? "GitHub" : scan.source === "sandbox" ? "Sandbox" : "ZIP"}</span></td><td><ScoreBadge score={scan.score} grade={scan.grade} /></td><td><span className="table-findings">{scan.findings.length}</span><small className="high-count">{scan.findings.filter((item) => ["critical", "high"].includes(item.severity)).length} high</small></td><td><span className="language-chips">{scan.languages?.slice(0, 2).map((item) => <i key={item.name}>{item.name}</i>)}</span></td><td className="muted-cell">{dateLabel(scan.created_at)}</td><td><ScanLink scan={scan}><ArrowRight size={14} /></ScanLink></td></tr>)}</tbody></table></div></div> : <EmptyState title={scans.length ? "No scans match this filter" : "Scan history starts here"} copy={scans.length ? "Try a different repository name or severity." : "Your completed scans will appear here with code locations, DPDP mappings, and scores."} action={!scans.length && <Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} />}
  </div>;
}

export function FindingsPage() {
  const query = useScans(); const findings = (query.data?.scans || []).flatMap((scan) => scan.findings.map((finding) => ({ ...finding, scan })));
  const [search, setSearch] = useState(""); const [severity, setSeverity] = useState("all");
  const visible = findings.filter(({ scan, ...finding }) => (severity === "all" || finding.severity === severity) && `${finding.title} ${finding.file} ${finding.pii_category} ${finding.rule_id} ${repoLabel(scan)}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><PageHeading kicker="DETERMINISTIC RESULTS" title="Findings" description="Every finding is tied to a rule, source location, data category, and DPDP section." /><ErrorBanner error={query.error} />
    <div className="filter-bar"><label className="filter-search"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search rule, file, category…" /></label><span className="filter-count">{visible.length} findings</span><select aria-label="Filter by severity" value={severity} onChange={(event) => setSeverity(event.target.value)}><option value="all">All severities</option>{severityOrder.map((item) => <option key={item} value={item}>{item}</option>)}</select></div>
    {query.isLoading ? <LoadingCard /> : visible.length ? <div className="console-card table-card"><div className="table-scroll"><table className="data-table full-table findings-table"><thead><tr><th>Finding</th><th>Repository</th><th>Location</th><th>Category</th><th>DPDP</th><th>Status</th><th /></tr></thead><tbody>{visible.map(({ scan, ...finding }) => <tr key={`${scan.id}:${finding.id}`}><td><div className="finding-title-cell"><SeverityTag severity={finding.severity} /><b>{finding.rule_id}</b><span>{finding.title}</span></div></td><td><ScanLink scan={scan}>{repoLabel(scan)}</ScanLink></td><td><code className="file-location">{finding.file}:{finding.line}</code></td><td><span className="category-pill">{finding.pii_category}</span></td><td><span className="dpdp-pill">{finding.dpdp_section}</span></td><td>{finding.verified ? <span className="status-pill status-verified"><Check size={12} /> Verified</span> : <span className="status-pill status-open">Open</span>}</td><td><Link to={`/workspace/scans/${scan.id}?finding=${encodeURIComponent(finding.id)}`} aria-label="Open finding"><ArrowRight size={14} /></Link></td></tr>)}</tbody></table></div></div> : <EmptyState title="No findings in this view" copy="Run a scan or change the active filters to see deterministic privacy findings." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} />}
  </div>;
}

type FixResponse = { status: string; verified: boolean; tier?: string | null; patch?: string; patch_preview?: string; explanation?: string; assumptions?: string[]; dpdp_section?: string; ai_available?: boolean; ai_notice?: string; verified_scan_id?: string; score_before?: number; score_after?: number; rescan?: { findings: number; files_scanned: number; parse_errors: number }; };

export function ScanDetailPage() {
  const { scanId } = useParams(); const query = useScan(scanId); const client = useQueryClient(); const { aiEnabled } = useContext(WorkspaceContext);
  const [searchParams, setSearchParams] = useSearchParams(); const [selected, setSelected] = useState<Finding | null>(null); const [archive, setArchive] = useState<File | null>(null); const [fixResult, setFixResult] = useState<FixResponse | null>(null); const [fixError, setFixError] = useState(""); const [severity, setSeverity] = useState("all");
  const [search, setSearch] = useState(""); const inputRef = useRef<HTMLInputElement | null>(null);
  const scan = query.data;
  useEffect(() => { const id = searchParams.get("finding"); if (id && scan) { const finding = scan.findings.find((item) => item.id === id); if (finding) setSelected(finding); } }, [searchParams, scan]);
  const visible = (scan?.findings || []).filter((finding) => (severity === "all" || finding.severity === severity) && `${finding.title} ${finding.file} ${finding.pii_category} ${finding.rule_id}`.toLowerCase().includes(search.toLowerCase()));
  async function requestFix() {
    if (!scan || !selected || !archive) { setFixError("Upload the exact ZIP snapshot that was scanned to verify a patch."); return; }
    setFixError(""); setFixResult(null);
    const form = new FormData(); form.append("file", archive); form.append("ai_enabled", String(aiEnabled));
    try {
      const result = await engineUpload<FixResponse>(`/api/v1/scans/${scan.id}/fixes/${selected.id}`, form);
      if (result.verified && result.patch) {
        const stored = readVerifiedPatches(scan.id); stored[selected.id] = result.patch;
        window.sessionStorage.setItem(`pl_verified_patches:${scan.id}`, JSON.stringify(stored));
      }
      setFixResult(result); await client.invalidateQueries({ queryKey: ["scan", scan.id] }); await client.invalidateQueries({ queryKey: ["scans"] });
    } catch (error) { setFixError(error instanceof Error ? error.message : "The fix could not be verified."); }
  }
  function closeDrawer() { setSelected(null); setArchive(null); setFixResult(null); setFixError(""); setSearchParams({}); }
  if (query.isLoading) return <LoadingCard label="Loading scan findings…" />;
  if (query.isError || !scan) return <div className="page-stack"><PageHeading kicker="SCAN DETAILS" title="Scan unavailable" description="This scan may have expired or belongs to another workspace." /><ErrorBanner error={query.error} /><Link className="text-action" to="/workspace/scans">Return to scan history <ArrowRight size={14} /></Link></div>;
  return <div className="page-stack"><div className="detail-back"><Link to="/workspace/scans"><ArrowLeft size={14} /> All scans</Link><span>/</span><span>{repoLabel(scan)}</span></div>
    <PageHeading kicker={`${scan.source.toUpperCase()} · ${dateLabel(scan.created_at)}`} title={repoLabel(scan)} description={`${scan.files_scanned} files analyzed · ${scan.languages?.map((item) => `${item.name} (${item.files})`).join(" · ") || "source"}`} action={<div className="detail-actions"><ScoreBadge score={scan.score} grade={scan.grade} /><Link className="secondary-action" to={`/workspace/graph/${scan.id}`}><Network size={14} /> Data flow</Link><Link className="secondary-action" to={`/workspace/inventory/${scan.id}`}><Boxes size={14} /> Inventory</Link><button className="secondary-action" onClick={async () => download(`${scan.repo}-privacylint.sarif`, "application/sarif+json", JSON.stringify(await engineGet(`/api/v1/scans/${scan.id}/sarif`), null, 2))}><ArrowDownToLine size={14} /> SARIF</button></div>} />
    <div className="detail-summary-grid"><div className="detail-summary-item"><span>POSTURE SCORE</span><b>{scan.score.toFixed(0)}<small>/100</small></b></div><div className="detail-summary-item"><span>FINDINGS</span><b>{scan.findings.length}</b></div><div className="detail-summary-item"><span>VERIFIED</span><b>{scan.findings.filter((item) => item.verified).length}</b></div><div className="detail-summary-item"><span>PARSE WARNINGS</span><b>{scan.parse_errors}</b></div><div className="detail-summary-item"><span>ERASURE COVERAGE</span><b>{scan.erasure_coverage?.percent ?? 100}<small>%</small></b></div></div>
    <section className="console-card results-card"><div className="results-toolbar"><div><h2>Code findings <span>{visible.length}</span></h2><p>Detections are deterministic. Snippets are redacted before storage.</p></div><div className="results-controls"><label className="mini-search"><Search size={14} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Filter findings" /></label><select aria-label="Filter finding severity" value={severity} onChange={(event) => setSeverity(event.target.value)}>{["all", ...severityOrder].map((value) => <option key={value} value={value}>{value === "all" ? "All severity" : value}</option>)}</select></div></div>
      {visible.length ? <div className="table-scroll"><table className="data-table full-table"><thead><tr><th>Severity / rule</th><th>Finding</th><th>Data category</th><th>Code location</th><th>DPDP section</th><th>Status</th><th /></tr></thead><tbody>{visible.map((finding) => <tr key={finding.id} className="clickable-row" onClick={() => { setSelected(finding); setSearchParams({ finding: finding.id }); }}><td><SeverityTag severity={finding.severity} /><b className="rule-id">{finding.rule_id}</b></td><td><div className="finding-name">{finding.title}<small>{finding.remediation}</small></div></td><td><span className="category-pill">{finding.pii_category}</span></td><td><code className="file-location">{finding.file}:{finding.line}</code></td><td><span className="dpdp-pill">{finding.dpdp_section}</span></td><td>{finding.verified ? <span className="status-pill status-verified"><Check size={12} /> Verified</span> : <span className="status-pill status-open">Open</span>}</td><td><ArrowRight size={14} /></td></tr>)}</tbody></table></div> : <EmptyState title="No findings in this scan" copy="This snapshot passed the selected deterministic rules." />}
    </section>
    {selected && <div className="drawer-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) closeDrawer(); }}><aside className="evidence-drawer" aria-label="Finding evidence"><div className="drawer-top"><span className="console-kicker">EVIDENCE INSPECTOR</span><button className="topbar-icon" aria-label="Close finding" onClick={closeDrawer}><X size={17} /></button></div><div className="drawer-content"><SeverityTag severity={selected.severity} /><h2>{selected.title}</h2><p className="drawer-rule">{selected.rule_id} · {selected.dpdp_section} {dpdpDescriptions[selected.dpdp_section] ? `· ${dpdpDescriptions[selected.dpdp_section]}` : ""}</p><div className="evidence-path"><div><span className="evidence-node source-node">SRC</span><span><b>{selected.pii_category} source</b><small>{selected.taint_path?.[0]?.file as string || selected.file}:{String(selected.taint_path?.[0]?.line ?? selected.line)}</small></span></div>{selected.taint_path?.slice(1).map((step, index) => <div key={`${step.file}-${step.line}-${index}`}><span className={`evidence-node ${step.kind === "sink" ? "sink-node" : "transform-node"}`}>{step.kind === "sink" ? "SINK" : String(step.kind).toUpperCase().slice(0, 4)}</span><span><b>{String(step.type || step.kind)}</b><small>{String(step.file)}:{String(step.line)}</small></span></div>)}</div><div className="code-evidence-head"><span>REDACTED EVIDENCE</span><code>{selected.file}:{selected.line}</code></div><pre className="code-evidence"><code>{selected.snippet}</code></pre><section className="dpdp-explainer"><span className="form-kicker">DPDP CONTEXT · {selected.dpdp_section}</span><p>{dpdpDescriptions[selected.dpdp_section] || "Review lawful purpose, safeguards, and data-principal rights."}</p><small>{selected.remediation}</small></section>
      {selected.verified ? <div className="verified-fix-card"><CircleCheck size={18} /><span><b>Verified by sandbox rescan</b><small>The deterministic scanner confirmed this finding is cleared.</small></span></div> : <section className="fix-request-card"><div className="fix-card-heading"><Sparkles size={15} /><b>Verify a fix</b><span>{aiEnabled ? "Template + Gemini" : "Offline template"}</span></div><p>Re-upload the exact source ZIP from this scan. A proposed patch is only marked resolved if parsing and deterministic rescan pass.</p><input ref={inputRef} type="file" accept=".zip,application/zip" onChange={(event) => setArchive(event.target.files?.[0] || null)} className="sr-only" /><button className="archive-select" onClick={() => inputRef.current?.click()}><Upload size={14} />{archive ? archive.name : "Choose original scan ZIP"}</button><button className="primary-action full-width" onClick={requestFix} disabled={!archive}><Sparkles size={14} /> Verify fix in sandbox</button><ErrorBanner error={fixError} />{fixResult && <div className={`fix-result ${fixResult.verified ? "fix-result-good" : "fix-result-guidance"}`}>{fixResult.verified ? <><div className="fix-result-head"><CircleCheck size={17} /><b>Verified · {fixResult.tier}</b></div><p>{fixResult.explanation}</p><small>Rescan: {fixResult.rescan?.findings} findings · {fixResult.rescan?.parse_errors} parse warnings · Score {fixResult.score_before} → {fixResult.score_after}</small>{fixResult.ai_notice && <small>{fixResult.ai_notice}</small>}{(fixResult.patch_preview || fixResult.patch) && <pre className="patch-preview">{fixResult.patch_preview || fixResult.patch}</pre>}</> : <><div className="fix-result-head"><CircleAlert size={17} /><b>Guidance only · no patch passed verification</b></div><p>{fixResult.explanation || "Review the recommended remediation and make a manual change."}</p>{fixResult.ai_available === false && aiEnabled && <small>Gemini is not configured on the analysis server. Configure GEMINI_API_KEY in the server environment.</small>}</>}</div>}</section>}
    </div></aside></div>}
  </div>;
}

export function LineagePage() {
  const scansQuery = useScans(); const { scanId } = useParams(); const scans = scansQuery.data?.scans || []; const selectedId = scanId || scans[0]?.id;
  if (scansQuery.isLoading) return <LoadingCard />;
  if (!selectedId) return <div className="page-stack"><PageHeading kicker="DATA FLOW MAP" title="Lineage graph" description="Follow personal data from collection to its sinks." /><EmptyState title="Nothing to map yet" copy="Run a repository scan to build its source-to-sink data flow graph." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} /></div>;
  return <GraphView scanId={selectedId} scans={scans} />;
}

export function InventoryPage() {
  const { scanId } = useParams(); const scansQuery = useScans(); const selectedId = scanId || scansQuery.data?.scans[0]?.id;
  const query = useQuery({ queryKey: ["inventory", selectedId], queryFn: () => engineGet<{ sdk_inventory: Array<{ name: string; versions: string[] }>; outbound_hosts: string[]; erasure_coverage: { stores: number; covered: number; percent: number } }>(`/api/v1/scans/${selectedId}/inventory`), enabled: Boolean(selectedId) });
  const scan = scansQuery.data?.scans.find((item) => item.id === selectedId);
  if (scansQuery.isLoading || query.isLoading) return <LoadingCard label="Loading SDK and erasure inventory…" />;
  if (!selectedId) return <div className="page-stack"><PageHeading kicker="REPOSITORY INVENTORY" title="SDKs & erasure" description="Outbound service hostnames and detected storage deletion coverage." /><EmptyState title="No scan inventory" copy="Run a repository scan to inspect manifests, outbound hosts, and erasure paths." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} /></div>;
  return <div className="page-stack"><PageHeading kicker={`INVENTORY · ${scan ? repoLabel(scan) : "SCAN"}`} title="SDKs & erasure" description="Outbound destinations are stored as hostnames only; URL paths and query strings are discarded." action={scansQuery.data && scansQuery.data.scans.length > 1 && <select aria-label="Choose scan" value={selectedId} onChange={(event) => window.location.assign(`/workspace/inventory/${event.target.value}`)}>{scansQuery.data.scans.map((item) => <option key={item.id} value={item.id}>{repoLabel(item)} · {item.id.slice(0, 6)}</option>)}</select>} />
    <ErrorBanner error={query.error || scansQuery.error} />
    <div className="inventory-summary-grid"><div className="inventory-stat"><span>DETECTED SDKs</span><b>{query.data?.sdk_inventory.length || 0}</b><small>from supported manifests</small></div><div className="inventory-stat"><span>OUTBOUND HOSTS</span><b>{query.data?.outbound_hosts.length || 0}</b><small>hostname only · no URL path</small></div><div className="inventory-stat"><span>ERASURE COVERAGE</span><b>{query.data?.erasure_coverage.percent ?? 100}<small>%</small></b><small>{query.data?.erasure_coverage.covered ?? 0} of {query.data?.erasure_coverage.stores ?? 0} stores mapped</small></div></div>
    <div className="dashboard-grid"><section className="console-card inventory-list-card"><div className="card-heading"><div><h2>SDK inventory</h2><p>Dependencies found in package and build manifests</p></div><Boxes size={16} /></div>{query.data?.sdk_inventory.length ? <div className="inventory-list">{query.data.sdk_inventory.map((sdk) => <div className="inventory-row" key={sdk.name}><span className="sdk-avatar"><Code2 size={15} /></span><span><b>{sdk.name}</b><small>Declared dependency</small></span><code>{sdk.versions.join(", ") || "version unspecified"}</code></div>)}</div> : <EmptyState title="No supported SDK manifests" copy="Dependency inventory is currently derived from package.json, requirements.txt, and pom.xml." />}</section>
      <section className="console-card inventory-list-card"><div className="card-heading"><div><h2>Outbound destinations</h2><p>External hostnames referenced in source</p></div><ExternalLink size={16} /></div>{query.data?.outbound_hosts.length ? <div className="host-list">{query.data.outbound_hosts.map((host) => <div className="host-row" key={host}><span className="host-dot" /><code>{host}</code><span>Source literal</span></div>)}</div> : <EmptyState title="No outbound hosts found" copy="Only hostnames are shown; sensitive URL paths and parameters are never returned." />}</section></div>
    <section className="console-card erasure-card"><div className="erasure-gauge"><b>{query.data?.erasure_coverage.percent ?? 100}<small>%</small></b><span>coverage</span></div><div><span className="console-kicker">DATA PRINCIPAL RIGHTS</span><h2>Erasure path coverage</h2><p>{query.data?.erasure_coverage.stores ? `${query.data.erasure_coverage.covered} of ${query.data.erasure_coverage.stores} detected data stores have a mapped deletion or retention path.` : "No data stores were identified in this scan. Coverage is not evidence that a deletion workflow exists outside the analyzed source."}</p><small>Static source analysis can miss dynamically constructed queries and external data stores.</small></div></section>
  </div>;
}

export function FixesPage() {
  const query = useScans(); const rows = (query.data?.scans || []).flatMap((scan) => scan.findings.map((finding) => ({ scan, finding })));
  const pending = rows.filter(({ finding }) => !finding.verified); const done = rows.filter(({ finding }) => finding.verified);
  return <div className="page-stack"><PageHeading kicker="REMEDIATION WORKFLOW" title="Fix workflow" description="Template and Gemini patches are suggestions until a sandbox rescan verifies the change." /><ErrorBanner error={query.error} />
    <div className="fix-overview-row"><div className="fix-state-card"><span className="metric-icon red"><ShieldAlert size={16} /></span><span><b>{pending.length}</b><small>findings to review</small></span></div><div className="fix-state-card"><span className="metric-icon green"><BadgeCheck size={16} /></span><span><b>{done.length}</b><small>rescan verified</small></span></div><div className="fix-state-note"><LockKeyhole size={15} /><span>Files stay client-side until you explicitly upload the matching ZIP to verify a selected patch.</span></div></div>
    {query.isLoading ? <LoadingCard /> : rows.length ? <div className="console-card table-card"><div className="table-scroll"><table className="data-table full-table"><thead><tr><th>Finding</th><th>Repository</th><th>Location</th><th>DPDP</th><th>Status</th><th /></tr></thead><tbody>{rows.map(({ scan, finding }) => <tr key={`${scan.id}:${finding.id}`}><td><div className="finding-title-cell"><SeverityTag severity={finding.severity} /><b>{finding.rule_id}</b><span>{finding.title}</span></div></td><td>{repoLabel(scan)}</td><td><code className="file-location">{finding.file}:{finding.line}</code></td><td><span className="dpdp-pill">{finding.dpdp_section}</span></td><td>{finding.verified ? <span className="status-pill status-verified"><Check size={12} /> Verified</span> : <span className="status-pill status-open">Needs review</span>}</td><td><Link className="row-action" to={`/workspace/scans/${scan.id}?finding=${encodeURIComponent(finding.id)}`}>{finding.verified ? "Evidence" : "Review fix"}<ArrowRight size={13} /></Link></td></tr>)}</tbody></table></div></div> : <EmptyState title="Nothing to remediate yet" copy="Scan a repository to see findings and propose sandbox-verified changes." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} />}
  </div>;
}

type GeneratedTest = { finding_id: string; rule_id: string; path: string; content: string; ci_snippet?: string; setup_config?: string | null; supported: boolean; framework?: string };
export function TestsPage() {
  const scansQuery = useScans(); const scans = scansQuery.data?.scans || []; const [scanId, setScanId] = useState(""); const [tests, setTests] = useState<GeneratedTest[]>([]); const [error, setError] = useState("");
  const activeId = scanId || scans[0]?.id; const active = scans.find((scan) => scan.id === activeId); const verified = active?.findings.filter((finding) => finding.verified) || [];
  useEffect(() => { if (active?.id) setTests([]); }, [active?.id]);
  async function generate() { if (!activeId) return; setError(""); try { const result = await enginePost<{ tests: GeneratedTest[] }>(`/api/v1/scans/${activeId}/tests`, { finding_ids: verified.map((finding) => finding.id) }); setTests(result.tests); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not generate regression tests."); } }
  if (scansQuery.isLoading) return <LoadingCard />;
  return <div className="page-stack"><PageHeading kicker="PERMANENT REGRESSION CHECKS" title="Regression tests" description="Tests are generated only for fixes that have passed the deterministic sandbox rescan." action={scans.length > 0 && <select aria-label="Choose scan" value={activeId} onChange={(event) => setScanId(event.target.value)}>{scans.map((scan) => <option key={scan.id} value={scan.id}>{repoLabel(scan)} · {scan.id.slice(0, 6)}</option>)}</select>} /><ErrorBanner error={scansQuery.error || error} />
    {!active ? <EmptyState title="No verified fixes yet" copy="Run a scan, then verify a fix from the evidence drawer. Regression generation stays locked until the rescan passes." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} /> : <><div className="testgen-banner"><div className="testgen-icon"><FileCode2 size={18} /></div><div><b>{verified.length ? `${verified.length} verified finding${verified.length === 1 ? "" : "s"} ready for regression coverage` : "No verified fixes in this scan"}</b><span>Framework detected: <strong>{active.test_framework || "static assertions"}</strong> · {active.repo}</span></div><button className="primary-action" disabled={!verified.length} onClick={generate}><Sparkles size={14} /> Generate tests</button></div>
      {!verified.length && <div className="info-callout"><LockKeyhole size={15} /><span>Unverified findings are intentionally excluded. Verify a change first from <Link to={`/workspace/scans/${active.id}`}>the scan detail page</Link>.</span></div>}
      {tests.length > 0 && <div className="generated-test-list">{tests.map((test) => <article className="console-card generated-test" key={test.finding_id}><div className="generated-test-header"><div><span className="status-pill status-verified"><Check size={12} /> Frozen assertions</span><h3>{test.path}</h3><p>{test.rule_id} · {test.framework || active.test_framework}</p></div><button className="secondary-action" onClick={() => download(test.path.split("/").pop() || "privacy-test", "text/plain", test.content)}><ArrowDownToLine size={14} /> Download</button></div><pre className="code-evidence"><code>{test.content}</code></pre>{test.ci_snippet && <div className="ci-snippet"><span>CI SNIPPET</span><code>{test.ci_snippet}</code></div>}</article>)}</div>}</>}
  </div>;
}

export function ReportsPage() {
  const query = useScans(); const scans = query.data?.scans || []; const [scanId, setScanId] = useState(""); const [format, setFormat] = useState("markdown"); const [error, setError] = useState("");
  const activeId = scanId || scans[0]?.id; const active = scans.find((scan) => scan.id === activeId);
  async function exportReport() {
    if (!active) return; setError("");
    try {
      if (format === "sarif") { const sarif = await engineGet(`/api/v1/scans/${active.id}/sarif`); download(`${active.repo}-privacy.sarif`, "application/sarif+json", JSON.stringify(sarif, null, 2)); return; }
      if (format === "json") { download(`${active.repo}-privacylint.json`, "application/json", JSON.stringify(active, null, 2)); return; }
      const severity = severityOrder.map((level) => `${level}: ${active.findings.filter((finding) => finding.severity === level).length}`).join(" · ");
      const body = `# PrivacyLint report — ${repoLabel(active)}\n\n- Scan: ${active.id}\n- Snapshot: \`${active.scan_hash}\`\n- Source: ${active.source}\n- Created: ${dateLabel(active.created_at)}\n- Privacy posture: **${active.score.toFixed(0)}/100 (Grade ${active.grade})**\n- Files analyzed: ${active.files_scanned}\n- Parse warnings: ${active.parse_errors}\n- Findings: ${active.findings.length} (${severity})\n- Erasure coverage: ${active.erasure_coverage?.percent ?? 100}%\n\n## Findings\n\n${active.findings.length ? active.findings.map((finding) => `### ${finding.rule_id} · ${finding.title}\n\n- Severity: ${finding.severity}\n- Data: ${finding.pii_category}\n- Evidence: \`${finding.file}:${finding.line}\`\n- DPDP: ${finding.dpdp_section} — ${dpdpDescriptions[finding.dpdp_section] || ""}\n- Status: ${finding.verified ? "sandbox rescan verified" : "open / unverified"}\n- Evidence snippet: \`${finding.snippet.replace(/`/g, "\\`")}\`\n- Remediation: ${finding.remediation}\n`).join("\n") : "No findings were produced for this scan."}\n\n## Limitations\n\nThe results are from deterministic static analysis of supported source files. A clean scan does not prove that all runtime data flows or external stores were detected.\n`;
      if (format === "html") {
        const escaped = body.replace(/[&<>]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[character]!));
        download(`${active.repo}-privacylint-report.html`, "text/html", `<!doctype html><meta charset="utf-8"><title>PrivacyLint report</title><style>body{max-width:900px;margin:40px auto;padding:0 20px;background:#0b0f14;color:#e7edf3;font:15px/1.7 Inter,Arial,sans-serif}pre{white-space:pre-wrap}h1,h2,h3{color:#2dd4bf}code{color:#a5f3e9}</style><pre>${escaped}</pre>`);
      } else download(`${active.repo}-privacylint-report.md`, "text/markdown", body);
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Report export failed."); }
  }
  if (query.isLoading) return <LoadingCard />;
  return <div className="page-stack"><PageHeading kicker="DETERMINISTIC REPORTS" title="Reports" description="Export findings, DPDP mappings, score facts, and scan methodology from a saved snapshot." action={scans.length > 0 && <select aria-label="Choose report scan" value={activeId} onChange={(event) => setScanId(event.target.value)}>{scans.map((scan) => <option key={scan.id} value={scan.id}>{repoLabel(scan)} · {scan.id.slice(0, 6)}</option>)}</select>} /><ErrorBanner error={query.error || error} />
    {!active ? <EmptyState title="No saved scans to report" copy="Reports are generated from deterministic scan results, never invented by AI." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Start a scan</Link>} /> : <div className="report-layout"><section className="console-card report-builder"><div className="report-icon"><FileText size={21} /></div><span className="console-kicker">REPORT BUILDER</span><h2>{repoLabel(active)}</h2><p>Choose a download format. SARIF is exported by the analysis service; Markdown, JSON, and HTML use saved scan facts.</p><div className="report-facts"><div><span>POSTURE</span><ScoreBadge score={active.score} grade={active.grade} /></div><div><span>FINDINGS</span><b>{active.findings.length}</b></div><div><span>SNAPSHOT</span><code>{active.scan_hash.slice(0, 14)}…</code></div></div><label className="console-field report-select"><span>Export format</span><select value={format} onChange={(event) => setFormat(event.target.value)}><option value="markdown">Markdown · auditor/developer</option><option value="html">HTML · printable report</option><option value="json">JSON · scan facts</option><option value="sarif">SARIF 2.1.0 · CI integrations</option></select></label><button className="primary-action full-width" onClick={exportReport}><ArrowDownToLine size={15} /> Download report</button><p className="report-footnote">For a PDF, open the downloaded HTML and use your browser’s Print → Save as PDF.</p></section><aside className="report-side"><section className="console-card report-type-card"><h3>Included in this export</h3><div><Check size={14} /> Scan score and grade</div><div><Check size={14} /> Rule, severity, and location</div><div><Check size={14} /> DPDP mapping and remediation</div><div><Check size={14} /> Redacted evidence snippets</div><div><Check size={14} /> Verification status and limitations</div></section><section className="info-callout"><LockKeyhole size={15} /><span>Reports are composed from the selected scan. Gemini does not generate or alter the findings and metrics.</span></section></aside></div>}
  </div>;
}

export function PrAutomationPage() {
  const query = useScans(); const [activeId, setActiveId] = useState(""); const [patches, setPatches] = useState<Record<string, string>>({});
  const [selectedIds, setSelectedIds] = useState<string[]>([]); const [token, setToken] = useState(""); const [error, setError] = useState("");
  const [created, setCreated] = useState<{ url: string; number: number; branch: string; files_changed: number; tests: number; score_before: number; score_after: number } | null>(null);
  const scans = query.data?.scans || []; const eligibleScans = scans.filter((scan) => scan.source === "github" && scan.owner && scan.findings.some((finding) => finding.verified));
  const activeScan = eligibleScans.find((scan) => scan.id === activeId) || eligibleScans[0]; const verified = activeScan?.findings.filter((finding) => finding.verified) || [];
  useEffect(() => { if (activeScan) { setActiveId(activeScan.id); setPatches(readVerifiedPatches(activeScan.id)); setSelectedIds([]); setCreated(null); setError(""); } }, [activeScan?.id]);
  const mutation = useMutation({
    mutationFn: async () => {
      if (!activeScan) throw new Error("Choose a GitHub scan with a verified fix.");
      if (!token.trim()) throw new Error("Enter a GitHub token with repository write access.");
      const fixes = selectedIds.map((findingId) => ({ finding_id: findingId, patch: patches[findingId] })).filter((item) => Boolean(item.patch));
      if (!fixes.length || fixes.length !== selectedIds.length) throw new Error("Select fixes whose verified patches are still available in this browser tab.");
      return enginePost<{ status: string; url: string; number: number; branch: string; files_changed: number; tests: number; score_before: number; score_after: number }>(`/api/v1/scans/${activeScan.id}/pull-request`, { github_token: token.trim(), fixes });
    },
    onSuccess: (result) => { setCreated(result); setError(""); setToken(""); },
    onError: (caught) => setError(caught instanceof Error ? caught.message : "GitHub could not create this pull request."),
    onSettled: () => setToken(""),
  });
  const selectedFiles = new Set(verified.filter((finding) => selectedIds.includes(finding.id)).map((finding) => finding.file));
  function toggleFinding(finding: Finding) { setSelectedIds((current) => current.includes(finding.id) ? current.filter((id) => id !== finding.id) : [...current, finding.id]); setCreated(null); }
  return <div className="page-stack"><PageHeading kicker="GITHUB WORKFLOW" title="PR automation" description="Re-check verified patches against the current branch, commit generated regression tests, and open a pull request." action={<a className="secondary-action" href="https://github.com/settings/personal-access-tokens" target="_blank" rel="noreferrer">Token settings <ExternalLink size={13} /></a>} /><ErrorBanner error={query.error || error} />
    {query.isLoading ? <LoadingCard label="Finding verified GitHub fixes…" /> : !eligibleScans.length ? <EmptyState title="No verified GitHub fixes yet" copy="Scan a GitHub repository, upload its exact ZIP to verify a fix, then return here to open a pull request." action={<Link className="primary-action small" to="/workspace/scans/new"><GitBranch size={14} /> Scan a repository</Link>} /> : <div className="pr-workflow-grid">
      <section className="console-card pr-connect-card"><div className="pr-connect-heading"><span className="pr-status-icon"><GitBranch size={19} /></span><div><span className="console-kicker">GITHUB CONNECTION</span><h2>Open a verified-fix PR</h2><p>PrivacyLint creates one branch and PR after it revalidates every selected patch on the unchanged scan snapshot.</p></div></div>
        <label className="console-field"><span>Scanned repository</span><select value={activeScan?.id || ""} onChange={(event) => setActiveId(event.target.value)}>{eligibleScans.map((scan) => <option key={scan.id} value={scan.id}>{repoLabel(scan)} · {scan.id.slice(0, 6)}</option>)}</select></label>
        <label className="console-field"><span>GitHub token <small>USED FOR THIS REQUEST ONLY</small></span><input type="password" autoComplete="new-password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="Fine-grained token with Contents + Pull requests write access" /></label>
        <div className="info-callout"><LockKeyhole size={14} /><span>Token is held in memory, sent to PrivacyLint’s local engine, used only with api.github.com, and never stored.</span></div>
        <button className="primary-action full-width" disabled={mutation.isPending || !selectedIds.length || !token.trim()} onClick={() => mutation.mutate()}>{mutation.isPending ? <><LoaderCircle size={15} className="spin" /> Creating branch and PR…</> : <><GitBranch size={15} /> Create GitHub pull request</>}</button>
        {created && <div className="pr-created-result"><div className="fix-result-head"><CircleCheck size={17} /><b>Pull request #{created.number} opened</b></div><p>{created.files_changed} files · {created.tests} generated tests · score {created.score_before.toFixed(0)} → {created.score_after.toFixed(0)}</p><code>{created.branch}</code><a className="text-action" href={created.url} target="_blank" rel="noreferrer">Review on GitHub <ExternalLink size={13} /></a></div>}
      </section>
      <section className="console-card pr-fixes-card"><div className="card-heading"><div><h2>Choose verified fixes</h2><p>Only sandbox-verified findings with a saved patch can be included. One fix per source file.</p></div><span className="filter-count">{verified.length} verified</span></div>
        {verified.map((finding) => { const hasPatch = Boolean(patches[finding.id]); const fileTaken = selectedFiles.has(finding.file) && !selectedIds.includes(finding.id); return <label className={`pr-fix-option${selectedIds.includes(finding.id) ? " selected" : ""}`} key={finding.id}><input type="checkbox" checked={selectedIds.includes(finding.id)} disabled={!hasPatch || fileTaken} onChange={() => toggleFinding(finding)} /><span className="rule-check"><Check size={11} /></span><span className="pr-fix-copy"><b>{finding.rule_id} · {finding.title}</b><small><code>{finding.file}:{finding.line}</code> · {finding.dpdp_section}</small></span><span className={`status-pill ${hasPatch ? "status-verified" : "status-open"}`}>{hasPatch ? "Patch ready" : "Re-verify"}</span></label>; })}
        {!verified.some((finding) => patches[finding.id]) && <p className="report-footnote">Verified patches are kept in this browser tab. Re-open the finding and verify its fix again if you started a new tab.</p>}
      </section>
    </div>}
  </div>;
}

export function BadgePage() {
  const query = useScans(); const repositories = (query.data?.scans || []).filter((scan) => scan.owner); const latestByRepo = [...new Map(repositories.map((scan) => [`${scan.owner}/${scan.repo}`, scan])).values()];
  return <div className="page-stack"><PageHeading kicker="PUBLIC POSTURE SIGNAL" title="Privacy badge" description="Embed the latest saved privacy score for a GitHub repository." /><ErrorBanner error={query.error} />
    {latestByRepo.length ? <div className="badge-grid">{latestByRepo.map((scan) => { const badgeUrl = `${window.location.protocol}//${window.location.hostname}:8000/api/v1/badge/${encodeURIComponent(scan.owner || "")}/${encodeURIComponent(scan.repo)}.svg`; return <article className="console-card badge-card" key={`${scan.owner}/${scan.repo}`}><div className="badge-card-top"><span className="repo-avatar"><Code2 size={14} /></span><span><b>{repoLabel(scan)}</b><small>Latest score · {dateLabel(scan.created_at)}</small></span><ScoreBadge score={scan.score} grade={scan.grade} /></div><div className="badge-preview"><img src={badgeUrl} alt={`PrivacyLint ${scan.grade} score badge for ${repoLabel(scan)}`} /></div><label className="console-field"><span>Markdown</span><input readOnly value={`[![PrivacyLint](${badgeUrl})](http://localhost:5173/workspace/scans/${scan.id})`} onFocus={(event) => event.currentTarget.select()} /></label><label className="console-field"><span>HTML</span><input readOnly value={`<img src="${badgeUrl}" alt="PrivacyLint ${scan.grade} score" />`} onFocus={(event) => event.currentTarget.select()} /></label><p className="report-footnote">Badge is public by design and shows only the repository score and grade.</p></article>; })}</div> : <EmptyState title="No GitHub scan to badge" copy="Run a GitHub repository scan to create a public SVG badge. ZIP-only scans do not have a public repository identity." action={<Link className="primary-action small" to="/workspace/scans/new"><Plus size={14} /> Scan GitHub repository</Link>} />}
  </div>;
}

export function SecurityPage() {
  const caps = useQuery({ queryKey: ["capabilities"], queryFn: () => engineGet<Capability>("/api/v1/capabilities") }); const scans = useScans();
  const controls = [
    ["Account sessions", "HttpOnly, SameSite session cookie with server-side expiry", "Code control"],
    ["Email verification", "6-digit, expiring, single-use OTP with attempt lockout", "Code control"],
    ["CSRF boundary", "Origin allowlist and CSRF token on state-changing requests", "Code control"],
    ["Request throttling", "Per-IP and per-email authentication rate limits", "Code control"],
    ["Archive intake", "ZIP size, path traversal, symlink, and expansion limits", "Code control"],
    ["Code execution", "Uploaded source is parsed and never executed by the scanner", "Code control"],
    ["Evidence redaction", "PII and secret values are redacted before persistence", "Code control"],
    ["Verified remediation", "Finding closes only after sandbox parse and rescan checks", "Code control"],
    ["Gemini boundary", "Server-side only; draft patches cannot decide findings", caps.data?.ai.configured ? "Configured" : "Key not configured"],
    ["Database / graph", "PostgreSQL and Neo4j are deployment integrations; local fallback is used here", caps.data?.lineage.backend || "Checking"],
  ] as const;
  return <div className="page-stack"><PageHeading kicker="CONTROL POSTURE" title="Security center" description="Current application safeguards and environment-dependent integrations." /><ErrorBanner error={caps.error || scans.error} />
    <div className="security-summary"><div className="security-summary-icon"><ShieldCheck size={20} /></div><div><b>Local workspace is operating</b><span>{caps.data?.analysis.offline_scanning ? "Deterministic scanning works offline. External services are shown separately below." : "Checking analysis capabilities…"}</span></div><span className="status-pill status-verified"><span className="status-dot" /> Active</span></div>
    <section className="console-card controls-card"><div className="card-heading"><div><h2>Control matrix</h2><p>Implemented controls are distinguished from deployment configuration.</p></div><span className="filter-count">{controls.length} controls</span></div><div className="control-list">{controls.map(([name, detail, status], index) => <div className="control-row" key={name}><span className="control-number">{String(index + 1).padStart(2, "0")}</span><span className="control-copy"><b>{name}</b><small>{detail}</small></span><span className={`control-status${status === "Code control" || status === "Configured" ? " control-ready" : ""}`}>{status === "Code control" || status === "Configured" ? <Check size={12} /> : <Clock3 size={12} />}{status}</span></div>)}</div></section>
    <section className="console-card audit-note-card"><div className="metric-icon indigo"><Activity size={16} /></div><div><h3>Audit events are recorded server-side</h3><p>Authentication and fix attempts are stored in service audit tables. A role-gated audit-log viewer is not exposed in this web release yet.</p></div></section>
  </div>;
}

export function RulesPage() {
  const query = useQuery({ queryKey: ["rules"], queryFn: () => engineGet<{ version: number; rules: Rule[] }>("/api/v1/rules") });
  const [selected, setSelected] = useState<string[] | null>(() => { try { const value = window.sessionStorage.getItem("pl_rules"); return value === null ? null : JSON.parse(value); } catch { return null; } });
  const rules = query.data?.rules || []; const active = selected ?? rules.map((rule) => rule.id);
  function update(ids: string[] | null) { setSelected(ids); if (ids === null) window.sessionStorage.removeItem("pl_rules"); else window.sessionStorage.setItem("pl_rules", JSON.stringify(ids)); }
  function toggle(id: string) { update(active.includes(id) ? active.filter((value) => value !== id) : [...active, id]); }
  return <div className="page-stack"><PageHeading kicker="DETERMINISTIC POLICY PACK" title="Rule configuration" description="Choose which YAML-backed privacy rules run on your next scan." action={<Link className="primary-action" to="/workspace/scans/new"><ScanLine size={14} /> New scan</Link>} /><ErrorBanner error={query.error} />
    <div className="rule-summary"><div><span className="console-kicker">ACTIVE CHECKS</span><b>{active.length}<small> / {rules.length}</small></b></div><p>Rule changes are held in this browser tab and apply to new scans. Existing scans keep their original rule selection.</p><button className="secondary-action" onClick={() => update(rules.map((rule) => rule.id))}>Enable all</button><button className="secondary-action" onClick={() => update(null)}>Reset default</button></div>
    {query.isLoading ? <LoadingCard label="Loading YAML rule catalog…" /> : <div className="rule-catalog">{rules.map((rule) => <label className={`console-card rule-card${active.includes(rule.id) ? " rule-active" : ""}`} key={rule.id}><input type="checkbox" checked={active.includes(rule.id)} onChange={() => toggle(rule.id)} /><span className="rule-check"><Check size={11} /></span><span className="rule-card-copy"><span><b>{rule.id}</b><i className={`rule-severity severity-${rule.severity}`}>{rule.severity}</i></span><strong>{rule.name}</strong><small>{rule.remediation}</small><em>{rule.dpdp_mapping} · {dpdpDescriptions[rule.dpdp_mapping] || ""}</em><small className="rule-languages">{rule.languages.join(" · ")}</small></span></label>)}</div>}
  </div>;
}

export function SettingsPage() {
  const caps = useQuery({ queryKey: ["capabilities"], queryFn: () => engineGet<Capability>("/api/v1/capabilities") }); const { aiEnabled, setAiEnabled, lightMode } = useContext(WorkspaceContext);
  return <div className="page-stack"><PageHeading kicker="WORKSPACE PREFERENCES" title="Settings" description="Configure per-session assistant behavior and review server-side integration status." /><ErrorBanner error={caps.error} />
    <section className="console-card settings-section"><div className="settings-section-head"><div className="settings-icon"><Sparkles size={18} /></div><div><h2>Gemini fixer</h2><p>Gemini can draft a fix for the deterministic finding. The sandbox remains the only verification gate.</p></div></div><div className="setting-row"><span><b>AI-assisted patch proposals</b><small>When off, PrivacyLint uses offline Tier-0 templates and remediation guidance.</small></span><button className={`settings-switch${aiEnabled ? " is-on" : ""}`} role="switch" aria-checked={aiEnabled} onClick={() => setAiEnabled(!aiEnabled)}><i /></button></div><div className="integration-status"><span>Provider</span><b>Google Gemini · {caps.data?.ai.model || "checking model…"}</b></div><div className="integration-status"><span>Server key status</span><b className={caps.data?.ai.configured ? "config-on" : "config-off"}>{caps.isLoading ? "Checking…" : caps.data?.ai.configured ? "Configured · key is not exposed to the browser" : "Not configured · offline mode remains available"}</b></div><div className="settings-help"><LockKeyhole size={14} /><span>Set <code>GEMINI_API_KEY</code> in the project’s server-side <code>.env</code>, restart the analysis service, then enable AI above. Never paste the key into a browser field.</span></div></section>
    <section className="console-card settings-section"><div className="settings-section-head"><div className="settings-icon"><Sun size={18} /></div><div><h2>Appearance</h2><p>Adjust the console display for this browser.</p></div></div><div className="setting-row"><span><b>Light theme</b><small>Preference is stored locally in this browser.</small></span><span className={`settings-static-pill${lightMode ? " active" : ""}`}>{lightMode ? "On" : "Off"}</span></div></section>
    <section className="console-card settings-section"><div className="settings-section-head"><div className="settings-icon"><FileText size={18} /></div><div><h2>Email delivery</h2><p>One-time codes are sent through the auth service’s SMTP transport.</p></div></div><div className="settings-help"><CircleAlert size={14} /><span>Configure <code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_USER</code>, and <code>SMTP_PASS</code> in the server environment. The Google OAuth client ID and secret alone cannot send mail; Gmail SMTP needs an App Password or a refresh token with mail-send permission.</span></div><p className="report-footnote">No OTP is returned by the API or shown in this interface. If SMTP is missing, registration reports an email-delivery error instead of displaying the code.</p></section>
  </div>;
}

function GraphView({ scanId, scans }: { scanId: string; scans: Scan[] }) {
  const query = useQuery({ queryKey: ["graph", scanId], queryFn: () => engineGet<Graph>(`/api/v1/scans/${scanId}/graph`) }); const container = useRef<HTMLDivElement | null>(null);
  const graphRef = useRef<Core | null>(null); const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null); const [graphError, setGraphError] = useState("");
  const scan = scans.find((item) => item.id === scanId); const nodeById = new Map((query.data?.nodes || []).map((node) => [node.id, node]));
  useEffect(() => {
    let cy: Core | undefined; let resize: (() => void) | undefined; let cancelled = false; setSelectedNode(null); setGraphError("");
    if (!query.data || !container.current) return;
    import("cytoscape").then((module) => {
      if (cancelled || !container.current) return;
      const create = module.default;
      const elements = [
        ...query.data.nodes.map((node) => {
          const props = node.properties || {};
          return { data: { id: node.id, label: String(props.label || node.kind), kind: node.kind, category: String(props.category || "") } };
        }),
        ...query.data.edges.map((edge) => ({
          data: { id: edge.id, source: edge.source, target: edge.target, type: edge.type, label: edge.type === "HAS_FINDING" ? "finding" : String(edge.properties?.sanitization || "flows") },
        })),
      ];
      cy = create({ container: container.current, elements, layout: { name: "preset" }, style: ([
        { selector: "node", style: { "background-color": "#34454f", label: "data(label)", color: "#e2ebef", "font-size": 11, "font-family": "DM Sans, sans-serif", "font-weight": 600, "text-wrap": "wrap", "text-max-width": 132, "text-valign": "center", "text-halign": "center", width: 148, height: 58, "border-width": 1.5, "border-color": "#60727d", "text-outline-width": 0 } },
        { selector: 'node[kind = "Source"]', style: { "background-color": "#12574f", "border-color": "#2dd4bf", shape: "round-rectangle" } },
        { selector: 'node[kind = "Route"], node[kind = "Controller"], node[kind = "Transform"]', style: { "background-color": "#263740", "border-color": "#66808c", shape: "round-rectangle" } },
        { selector: 'node[kind = "SinkLog"], node[kind = "SinkResponse"], node[kind = "SinkThirdParty"], node[kind = "SinkClientStorage"]', style: { "background-color": "#642f3a", "border-color": "#fb7185" } },
        { selector: 'node[kind = "Store"]', style: { "background-color": "#303c78", "border-color": "#9b9afa", shape: "round-rectangle" } },
        { selector: 'node[kind = "Finding"]', style: { "background-color": "#6e4819", "border-color": "#fbbf24", shape: "diamond", width: 102, height: 82, "font-size": 10 } },
        { selector: "node:selected", style: { "border-width": 3, "border-color": "#f6fbfd", "overlay-color": "#2dd4bf", "overlay-opacity": 0.12 } },
        { selector: "edge", style: { width: 2, "line-color": "#546b77", "target-arrow-color": "#8ea3ad", "target-arrow-shape": "triangle", "arrow-scale": 1.1, "curve-style": "bezier", label: "data(label)", color: "#a8bac2", "font-size": 9, "font-family": "DM Mono, monospace", "text-background-color": "#10171e", "text-background-opacity": 1, "text-background-padding": 3 } },
        { selector: 'edge[type = "HAS_FINDING"]', style: { "line-style": "dashed", "line-color": "#b98435", "target-arrow-color": "#e1b45e" } },
      ] as never) });
      graphRef.current = cy;
      cy.on("tap", "node", (event) => { cy?.nodes().unselect(); event.target.select(); setSelectedNode(nodeById.get(event.target.id()) || null); });
      cy.on("tap", "edge", () => setSelectedNode(null));
      cy.one("layoutstop", () => { if (!cancelled) cy?.fit(undefined, 52); });
      resize = () => cy?.resize(); window.addEventListener("resize", resize);
      cy.layout({ name: "breadthfirst", directed: true, roots: query.data.nodes.filter((node) => node.kind === "Source").map((node) => node.id), padding: 62, spacingFactor: 1.28, avoidOverlap: true, nodeDimensionsIncludeLabels: true }).run();
    }).catch(() => { if (!cancelled) setGraphError("The lineage renderer could not load. Reload this page and try again."); });
    return () => { cancelled = true; if (resize) window.removeEventListener("resize", resize); graphRef.current = null; cy?.destroy(); };
  }, [query.data]);
  const layoutOptions = { name: "breadthfirst", directed: true, roots: query.data?.nodes.filter((node) => node.kind === "Source").map((node) => node.id) || [], padding: 62, spacingFactor: 1.28, avoidOverlap: true, nodeDimensionsIncludeLabels: true };
  const selectedProperties = selectedNode?.properties || {};
  const category = selectedProperties.category == null ? "" : String(selectedProperties.category);
  const file = selectedProperties.file == null ? "" : String(selectedProperties.file);
  const line = selectedProperties.line == null ? "" : String(selectedProperties.line);
  const sinkType = selectedProperties.sink_type == null ? "" : String(selectedProperties.sink_type);
  const dpdpSection = selectedProperties.dpdp_section == null ? "" : String(selectedProperties.dpdp_section);
  const severity = selectedProperties.severity == null ? "" : String(selectedProperties.severity);
  const findingId = selectedProperties.finding_id == null ? "" : String(selectedProperties.finding_id);
  return <div className="page-stack"><PageHeading kicker="SOURCE TO SINK" title="Data lineage" description="Follow each detected data category from source through code paths to its sink." action={<div className="detail-actions">{scans.length > 1 && <select value={scanId} onChange={(event) => window.location.assign(`/workspace/graph/${event.target.value}`)} aria-label="Choose scan">{scans.map((item) => <option key={item.id} value={item.id}>{repoLabel(item)} · {item.id.slice(0, 6)}</option>)}</select>}<button className="secondary-action" onClick={() => graphRef.current?.fit(undefined, 52)} disabled={!query.data?.nodes.length}><ScanLine size={14} /> Fit graph</button><button className="secondary-action" onClick={() => graphRef.current?.layout(layoutOptions as never).run()} disabled={!query.data?.nodes.length}><Activity size={14} /> Re-layout</button><button className="secondary-action" onClick={async () => download(`${scan?.repo || "scan"}-lineage.graphml`, "application/graphml+xml", await engineText(`/api/v1/scans/${scanId}/graph?format=graphml`))}><ArrowDownToLine size={14} /> GraphML</button><button className="secondary-action" onClick={async () => download(`${scan?.repo || "scan"}-lineage.svg`, "image/svg+xml", await engineText(`/api/v1/scans/${scanId}/graph?format=svg`))}><ArrowDownToLine size={14} /> SVG</button><button className="secondary-action" onClick={async () => downloadBlob(`${scan?.repo || "scan"}-lineage.png`, await engineBlob(`/api/v1/scans/${scanId}/graph?format=png`))}><ArrowDownToLine size={14} /> PNG</button></div>} />
    <ErrorBanner error={query.error || graphError} />
    <div className="graph-legend"><span><i className="legend-source" /> Personal-data source</span><span><i className="legend-process" /> Route / controller</span><span><i className="legend-store" /> Data store</span><span><i className="legend-sink" /> Exposed sink</span><span><i className="legend-finding" /> Finding</span><small>Click a node to inspect its evidence.</small></div>
    <section className="console-card graph-card"><div className="graph-canvas-toolbar"><div><b>{scan ? repoLabel(scan) : "Selected scan"}</b><span>{query.data?.nodes.length || 0} nodes · {query.data?.edges.length || 0} relationships</span></div><span className="graph-layout-hint"><Network size={13} /> Source flows downward to the detected sink</span></div><div ref={container} className="cytoscape-canvas" aria-label="Interactive privacy data flow graph" />{query.isLoading && <div className="graph-overlay"><LoadingCard label="Building scan lineage…" /></div>}{query.data && !query.data.nodes.length && <div className="graph-empty"><EmptyState title="No source-to-sink flow found" copy="This scan has no findings with lineage evidence. Open the scan findings to inspect the detected code locations." action={<Link className="text-action" to={`/workspace/scans/${scanId}`}><ArrowRight size={14} /> Review scan findings</Link>} /></div>}{selectedNode && <aside className="graph-node-inspector"><div className="graph-inspector-top"><span className={`graph-node-kind kind-${selectedNode.kind.toLowerCase()}`}>{selectedNode.kind}</span><button className="icon-button" aria-label="Close node details" onClick={() => setSelectedNode(null)}><X size={14} /></button></div><h3>{String(selectedProperties.label || selectedNode.kind)}</h3><dl>{category && <div><dt>Data category</dt><dd>{category}</dd></div>}{file && <div><dt>Code location</dt><dd><code>{file}{line ? `:${line}` : ""}</code></dd></div>}{sinkType && <div><dt>Sink</dt><dd>{sinkType}</dd></div>}{dpdpSection && <div><dt>DPDP mapping</dt><dd>{dpdpSection}</dd></div>}{severity && <div><dt>Severity</dt><dd>{severity}</dd></div>}</dl>{findingId && <Link className="text-action graph-evidence-link" to={`/workspace/scans/${scanId}?finding=${encodeURIComponent(findingId)}`}>Open finding evidence <ArrowRight size={14} /></Link>}</aside>}</section>
    <div className="graph-footer"><Network size={14} /><span>{query.data?.nodes.length || 0} nodes</span><span>{query.data?.edges.length || 0} relationships</span><span>Backend: {query.data?.backend || "NetworkX"}</span></div>
  </div>;
}
